let r = $json.report; if (typeof r === 'string') { try { r = JSON.parse(r); } catch(e){ r = {}; } }
r = r || {};
const g = (k) => Number(r[k] || 0);
const reg = g('registered'), act = g('active7');
const pct = reg > 0 ? Math.round(act / reg * 100) : 0;
const unk = g('sex_unknown');
const L = [];
L.push('📊 <b>Отчёт по пользователям за неделю</b>');
L.push('');
L.push('👥 Всего зарегистрировано: <b>' + reg + '</b> (♂ ' + g('male') + ' · ♀ ' + g('female') + (unk > 0 ? (' · пол не указан ' + unk) : '') + ')');
L.push('🆕 Новых за неделю: <b>' + g('new7') + '</b>');
L.push('✅ Онбординг завершили: ' + g('onboarded') + ' из ' + reg);
L.push('');
L.push('🟢 Активны за неделю: <b>' + act + '</b> из ' + reg + ' (' + pct + '%)');
L.push('   из них ♂ ' + g('active_male') + ' · ♀ ' + g('active_female'));
L.push('');
L.push('<b>🔧 Использовали фичи за неделю (чел.):</b>');
L.push('🏋️ дневник тренировок: ' + g('feat_workout'));
L.push('🍽️ дневник питания: ' + g('feat_food'));
L.push('📏 измерения: ' + g('feat_meas'));
L.push('🔬 /research: ' + g('feat_research'));
L.push('🥗 рецепты: ' + g('feat_recipe'));
L.push('🎤 голосовые: ' + g('feat_voice'));
L.push('📸 фото: ' + g('feat_photo'));
L.push('📄 документы: ' + g('feat_document'));
return [{ json: { text: L.join('\n') } }];
